mapper.select:
select t.username, t.nickname, t.mobile, t.email, t.enabled from la_users t



            t.tenant_id = #{parameters.tenantId}


            t.tenant_id is null




            and t.username not in (select username from la_user_roles where authority in ('ROLE_DEV','ROLE_TENANT','ROLE_SYSTEM'))


            and t.username not in (select username from la_user_roles where authority = 'ROLE_TENANT')



        and t.username in (select username from la_user_roles where authority = #{parameters.authority})


        and t.username in #{item}


        and t.nickname like #{parameters.nickname}


        and (t.username like #{parameters.keyword} or t.nickname like #{parameters.keyword} or t.mobile like #{parameters.keyword} or t.email like #{parameters.keyword})


        and t.mobile like #{parameters.mobile}


        and t.email like #{parameters.email}


        and t.username in (select username from la_user_organization where organization_id in #{item})


        and t.username in (select username from la_user_fields where

            field_name = #{item.fieldName} and field_value = #{item.fieldValue}


            group by username having count(1) = #{parameters.userFields.size}
        )




                and t.username in (select username from la_user_online_logs where is_online = 1)


                and t.username not in (select username from la_user_online_logs where is_online = 1)




order by t.created_at desc, t.username

select t5.username from (select t.authority, t.alias from la_roles t ) t1 left join (select t3.username, t2.authority, t4.organization_id as orgid, t3.nickname from la_user_roles t2 inner join la_users t3 on t2.username = t3.username inner join la_user_organization t4 on t3.username = t4.username) t5 on t1.authority = t5.authority
t1.authority = #{authority}
and t5.orgid = #{orgId}

mapper.update:
update la_users set
    nickname = #{nickname},
    mobile = #{mobile, jdbcType=VARCHAR},
    email = #{email, jdbcType=VARCHAR},
    expired_time = #{expiredTime, jdbcType=TIMESTAMP}

        ,tenant_id = #{tenantId, jdbcType=VARCHAR}

where username = #{username}

mapper.select:
select t.username from la_users t
inner join la_user_roles ur on ur.username = t.username
inner join la_user_organization uo on t.username = uo.username
where uo.organization_id = #{orgId}

    and ur.authority = #{roleId}

select t.resource_id,t.la_manage from la_role_resources t


        t.authority = #{authority}


        and t.la_manage = #{manage}


        and  t.resource_id  in

            #{item}



group by  t.resource_id ,t.la_manage

select distinct t1.username, t1.nickname from la_users t1 left join la_user_organization t2 on t1.username = t2.username
t1.tenant_id = #{tenantId}
and t2.organization_id in
#{item}

select username from la_users t1 inner join la_user_organization t2 on t1.username = t2.username


        t2.organization_id in (select t.id from la_organization t where t.parent_keys like concat(concat('%', #{orgId}), '%') or t.id = #{orgId})


       and t2.organization_id = #{orgId}

select distinct(t.username), t.nickname, t.mobile, t.email, t.enabled, t.created_at as created_at, mi.username as userid, mi.avatar, mi.remark, mi.identity_id , mi.position , mi.status, mi.emp_no, mi.dd_no, mi.wechat_no, mi.password_reset_required, o.orgid, o.alias as orgalias, r.authority, r.alias, mi.extend_param, tc.nickname created_by from la_users t left join la_user_info mi on t.username = mi.username left join (select ur.authority,mr.alias,ur.username from la_user_roles ur left join la_roles mr on ur.authority = mr.authority) r on t.username = r.username left join (select mo.id orgid, uo.username, mo.alias from la_user_organization uo left join la_organization mo on uo.organization_id = mo.id where mo.id is not null) o on t.username = o.username left join (select nickname, username from la_users) tc on t.created_by = tc.username
left join la_user_roles ur on ur.username = t.username
t.tenant_id = #{parameters.tenantId}
t.tenant_id is null
and t.username in #{item}
and t.username not in (select username from la_user_roles where authority in ('ROLE_DEV', 'ROLE_SYSTEM') or authority like 'ROLE_TENANT@%')
and t.username not in (select username from la_user_roles where authority like 'ROLE_TENANT@%')
and t.nickname like #{parameters.nickname}
and t.mobile like #{parameters.mobile}
and t.email like #{parameters.email}
and ur.authority = #{parameters.authority}
and o.orgid in #{item}
and exists ( select 1 from la_user_fields uf where uf.username = t.username and uf.field_name = #{item.fieldName} and uf.field_value = #{item.fieldValue} and (uf.tenant_id is null or uf.tenant_id = t.tenant_id) )
order by t.created_at desc, username asc
